unsafe extern "C" fn game_fallattack(agent: &mut L2CAgentBase) {
    let lua_state = agent.lua_state_agent;
    let boma = agent.boma();
    let owner_id = WorkModule::get_int(boma, *WEAPON_INSTANCE_WORK_ID_INT_LINK_OWNER) as u32;
    let owner = utils::util::get_battle_object_from_id(owner_id);
    let owner_boma = &mut *(*owner).module_accessor;
    if is_excute(agent) {
        if sv_battle_object::kind(owner_id) == *FIGHTER_KIND_PICKEL 
        && !owner_boma.is_motion_one_of(&[
            Hash40::new("attack_air_lw"),
            Hash40::new("attack_air_lw_2"),
            Hash40::new("attack_air_lw_fall")
        ]) {
            wait(lua_state, 2.0);
        }
        let fall_distance = VarModule::get_float(boma.object(), START_Y_POS) - PostureModule::pos_y(boma);
        let dmg = 8.0 + (fall_distance / 5.0);
        let kbg = 100.0 - (fall_distance / 1.5);
        let sfx = if fall_distance >= 16.0 { *ATTACK_SOUND_LEVEL_L } else { *ATTACK_SOUND_LEVEL_M };
        ATTACK(agent, 0, 0, Hash40::new("top"), dmg, 70, kbg, 0, 62, 5.0, 0.0, 5.8, 0.0, Some(0.0), Some(5.8), Some(0.0), 0.7, 1.0, *ATTACK_SETOFF_KIND_ON, *ATTACK_LR_CHECK_POS, false, 7, 0.0, 0, true, false, false, false, false, *COLLISION_SITUATION_MASK_A, *COLLISION_CATEGORY_MASK_ALL, *COLLISION_PART_MASK_ALL, false, Hash40::new("collision_attr_normal"), sfx, *COLLISION_SOUND_ATTR_HEAVY, *ATTACK_REGION_OBJECT);
        ATTACK(agent, 1, 0, Hash40::new("top"), dmg, 58, kbg, 0, 62, 5.0, 0.0, 5.8, 0.0, Some(0.0), Some(5.8), Some(0.0), 0.7, 1.0, *ATTACK_SETOFF_KIND_ON, *ATTACK_LR_CHECK_POS, false, 7, 0.0, 0, true, false, false, false, false, *COLLISION_SITUATION_MASK_G, *COLLISION_CATEGORY_MASK_ALL, *COLLISION_PART_MASK_ALL, false, Hash40::new("collision_attr_normal"), sfx, *COLLISION_SOUND_ATTR_HEAVY, *ATTACK_REGION_OBJECT);
        AttackModule::set_attack_height_all(boma, AttackHeight(*ATTACK_HEIGHT_HIGH), false);
    }
}

